#!/usr/bin/env python3
"""Offline typed Let's Encrypt DTO and contract generation from pinned sources."""
import json,subprocess,hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
source=ROOT/'catalog/sources/lets-encrypt-certificates.json'
x=json.loads(source.read_text())
fields={'created_at':'CreatedAt','deleted_at':'DeletedAt','domains':'Domains','error_description':'ErrorDescription','expire_at':'ExpireAt','id':'ID','knox_cert_id':'KnoxCertID','name':'Name','project_id':'ProjectID','status':'Status','updated_at':'UpdatedAt','version':'Version'}
lines=['// Code generated by letsencryptgen; DO NOT EDIT.','package letsencrypt','import "github.com/festy23/selectel-sdk/types"','type Certificate struct { Ref types.ResourceRef `json:"ref"`']
for prop,schema in x['definitions']['response.LeCert']['properties'].items():
 typ='[]string' if prop=='domains' else '*types.Integer' if prop=='version' else '*types.ProtectedValue' if prop=='error_description' else '*string'
 lines.append(fields[prop]+' '+typ+' `json:"'+prop+',omitempty"`')
lines+=['}','type IssueRequest struct { Domains []string `json:"domains"`; Name string `json:"name"` }','type IssueOptions struct { DNSV2 *bool }']
p=ROOT/'letsencrypt/types_generated.go';p.write_text('\n'.join(lines)+'\n');subprocess.run(['gofmt','-w',str(p)],check=True)
# Only implemented public slices receive bindings.
b=json.loads((ROOT/'catalog/bindings.json').read_text())
operation='certificates.le_v1.certificates.list'
contract={'operation_id':operation,'source':'https://docs.selectel.ru/api/lets-encrypt-certificates.json GET /; URL table https://docs.selectel.ru/api/urls/ fetched 2026-10-16','source_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'endpoint':'https://api.selectel.ru/certs/le exact override permitted; distinct from User Certificate API','auth':'project scoped IAM X-Auth-Token','request':{'method':'GET','path':'/','mapping':'no server pagination/filter invented'},'response':{'mapping':'all response.LeCert fields; raw timestamp strings, exact integer version, protected error_description, unique nonempty IDs and exact project owner','sensitive_fields':['error_description']},'errors':{'shared':'shared status mapping; discard raw provider text'},'retry':'bounded safe read','pagination':'fixed provider array; bounded replay+skip; scope/generation/endpoint ID+resolved URL/revision bound cursor; malformed prefix remains incomplete','recovery':'none','wait':{'goals':[]}}
(ROOT/'catalog/contracts'/f'{operation}.json').write_text(json.dumps(contract,indent=2)+'\n')
b[operation]={'go_method':'letsencrypt.List','input_type':'pagination.Options','output_type':'pagination.Iterator[letsencrypt.Certificate]','status':'implemented','contract_ref':f'contracts/{operation}.json','covered_schema_ref':f'contracts/{operation}.json#/request','excluded_variants':[],'files':['client.go','letsencrypt/client.go','letsencrypt/types_generated.go','internal/letsencryptgen/generate.py','internal/letsencryptgen/assets/urls-excerpt.txt','internal/core/reads.go','internal/core/request.go','internal/core/auth.go','generate.go'],'evidence_files':['letsencrypt/client_public_test.go'],'evidence_ref':'letsencrypt/client_public_test.go','recovery':False,'wait_goals':[]}
(ROOT/'catalog/bindings.json').write_text(json.dumps(b,indent=2)+'\n')
operation='certificates.le_v1.certificates.issue'
contract={'operation_id':operation,'source':'lets-encrypt-certificates.json POST /issue; URL table excerpt','source_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'endpoint':'https://api.selectel.ru/certs/le exact scoped endpoint','auth':'project scoped IAM X-Auth-Token','request':{'method':'POST','path':'/issue','mapping':'required domains/name source fields; optional dnsv2 nil omitted, explicit false/true preserved; no implicit legacy migration or availability claim'},'response':{'mapping':'200 Accepted; extract exact nonempty ID and matching project before remaining DTO; trusted ID retained after malformed unrelated metadata; protected error_description','sensitive_fields':['error_description']},'errors':{'shared':'normal HTTP mapping; discard raw provider text','rejected_statuses':[400,401,403]},'retry':'never replay mutation after Unknown','pagination':None,'recovery':'exact ID observation through bounded complete List only; no name lookup/adoption/creation proof; no ID for unknown create unavailable','wait':{'goals':[]}}
(ROOT/'catalog/contracts'/f'{operation}.json').write_text(json.dumps(contract,indent=2)+'\n')
b[operation]=dict(b['certificates.le_v1.certificates.list'],go_method='letsencrypt.Issue',input_type='letsencrypt.IssueRequest, letsencrypt.IssueOptions, types.CallOptions',output_type='letsencrypt.Certificate',contract_ref=f'contracts/{operation}.json',covered_schema_ref=f'contracts/{operation}.json#/request')
(ROOT/'catalog/bindings.json').write_text(json.dumps(b,indent=2)+'\n')
operation='certificates.le_v1.certificates.delete'
contract={'operation_id':operation,'source':'lets-encrypt-certificates.json DELETE /{id}; URL table excerpt','source_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'endpoint':'exact selected endpoint from caller ref','auth':'project scoped IAM','request':{'method':'DELETE','path':'/{id}','mapping':'exact lets_encrypt_certificate reference; no name search or user_certificate ref reuse'},'response':{'mapping':'204 Accepted, original exact reference retained','sensitive_fields':[]},'errors':{'shared':'shared status mapping; provider error text discarded','rejected_statuses':[400,401,403,404]},'retry':'never replay unknown mutation','pagination':None,'recovery':'exact ID observation only, no mutation replay','wait':{'goals':[]}}
(ROOT/'catalog/contracts'/f'{operation}.json').write_text(json.dumps(contract,indent=2)+'\n')
b[operation]=dict(b['certificates.le_v1.certificates.list'],go_method='letsencrypt.Delete',input_type='types.ResourceRef, types.CallOptions',output_type='struct{}',contract_ref=f'contracts/{operation}.json',covered_schema_ref=f'contracts/{operation}.json#/request')
(ROOT/'catalog/bindings.json').write_text(json.dumps(b,indent=2)+'\n')
for operation,entry in b.items():
 if not operation.startswith('certificates.le_v1.'):continue
 path=ROOT/'catalog/contracts'/f'{operation}.json';contract=json.loads(path.read_text())
 contract['recovery']='Root Resource/Resume validate exact scope/generation/kind/endpoint and receipt revision/effect. Unknown exact ID observation through bounded complete List stays indeterminate; never name adoption or replay. Known no-ref terminal receipts Recover conclusively without I/O; no resource state inferred.'
 contract['wait']={'goals':['active','deleted'],'mapping':'active only active; creating/validating/issuing/renewing pending, error/invalid/deleted fail; deleted goal accepts deleted or absent in complete bounded list only. No DNS propagation or consumer application proof.'}
 path.write_text(json.dumps(contract,indent=2)+'\n')
 entry['files']=sorted(set(entry['files']+['letsencrypt/handle.go','operations/handle.go','pagination/pagination.go','docs/modules/selectelsdk/letsencrypt.md']))
 entry['recovery']=not operation.endswith('.list');entry['wait_goals']=[] if operation.endswith('.list') else ['deleted'] if operation.endswith('.delete') else ['active']
 contract['wait']['goals']=entry['wait_goals'];path.write_text(json.dumps(contract,indent=2)+'\n')
(ROOT/'catalog/bindings.json').write_text(json.dumps(b,indent=2)+'\n')
